<?php/** * 第三方接口 */namespace app\api\service\public;use app\api\service\CommService;use app\common\Httprequest;use think\facade\Env;use think\facade\Log;class ThirdApiService extends CommService{    public function __construct($param)    {        parent::_initialize($param);    }    public function doQuery($data)    {        $url = Env::get('third.query_url');        $res = $this->doRrequest($url, $data);        return $res;    }    private function doRrequest($url, $data)    {        $username = Env::get('third.username');        $password = Env::get('third.password');        Log::info('[ThirdApi]请求地址' . $url);        Log::info('[ThirdApi]请求参数' . json_encode($data));        $resp = Httprequest::sendBasicAuthRequest($url, $data, $username, $password);        Log::info('[ThirdApi]返回结果' . $resp);        $res = json_decode($resp, true);        if ($res['code'] != 'ok') {            throwError($res['message'] ?? '未知错误');        }        if (isset($res['bizCode'])) {            throwError($res['message'] ?? '未知错误');        }        return $res;    }    public function doSubmit($data)    {        $url = Env::get('third.submit_url');        $res = $this->doRrequest($url, $data);        return $res;    }}